  // coin collection
  for (let i = coins.length - 1; i >= 0; i--) {
    const c = coins[i];
    if (distance(player.x, player.y, c.x, c.y) < c.radius + player.size) {
      score++;
      coins.splice(i, 1);
      spawnCoin();
    }
  }

  // collision with orbs -> game over
  for (const o of orbs) {
    if (distance(player.x, player.y, o.x, o.y) < o.radius + player.size) {
      gameOver = true;
      break;
    }
  }
};

input.newString:
const update = () => {
  if (gameOver) return;
  player.update();

  // update orbs
  for (let i = orbs.length - 1; i >= 0; i--) {
    const o = orbs[i];
    o.x += o.vx;
    o.y += o.vy;
    o.radius += o.growth;
    // remove if out of screen far enough
    if (o.x < -100 || o.x > canvas.width + 100 || o.y < -100 || o.y > canvas.height + 100) {
      orbs.splice(i, 1);
      spawnOrb();
    }
  }

  // update particles (explosions)
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.life--;
    p.radius *= 0.96;
    if (p.life <= 0 || p.radius < 0.5) {
      particles.splice(i, 1);
    }
  }

  // coin collection
  for (let i = coins.length - 1; i >= 0; i--) {
    const c = coins[i];
    if (distance(player.x, player.y, c.x, c.y) < c.radius + player.size) {
      score++;
      // create small burst on collect
      spawnParticle(c.x, c.y);
      coins.splice(i, 1);
      spawnCoin();
    }
  }

  // collision with orbs -> game over with explosion
  for (const o of orbs) {
    if (distance(player.x, player.y, o.x, o.y) < o.radius + player.size) {
      gameOver = true;
      // spawn explosion particles at player location
      spawnParticle(player.x, player.y);
      break;
    }
  }
};

